css:
@page { size: A4; margin: 8mm; }
@font-face {
  font-family: 'Noto Naskh Arabic';
  src: url('/assets/tms/fonts/NotoNaskhArabic-VariableFont_wght.ttf') format('truetype');
  font-weight: 400 700;
  font-style: normal;
}
@font-face {
  font-family: 'SaudiRiyalSymbol';
  src: url('/assets/tms/fonts/saudiriyalsymbol.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
}
body, .print-format {
  font-family: 'Ubuntu', 'Segoe UI', Arial, sans-serif;
  font-size: 11px;
  color: #111827;
}
[dir="rtl"], .ar, .text-right, th, td:first-child {
  font-family: 'Noto Naskh Arabic', serif;
}
.table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.table th,
.table td {
  border: 1px solid #cbd5e1;
  padding: 5px 6px !important;
  vertical-align: top !important;
  line-height: 1.3;
}
.table th {
  background: #eef6f5;
  color: #0f766e;
  font-weight: 700;
}
.num {
  direction: ltr;
  text-align: right;
  white-space: nowrap;
  font-family: 'Ubuntu', 'Segoe UI', Arial, sans-serif;
}
.currency-symbol {
  font-family: 'SaudiRiyalSymbol', 'Ubuntu', sans-serif;
  font-size: 1.05em;
  font-weight: normal;
  vertical-align: -0.02em;
}
.invoice-qr {
  width: 118px;
  height: 118px;
  object-fit: contain;
  display: block;
}
